SELECT COUNT(*)
  FROM tb_completions cp
  JOIN tb_enrollments e ON e.id = cp.enrollment_id
 WHERE e.user_id = #{userId}
   AND e.course_id = #{courseId}
   AND cp.status = 'COMPLETED'

SELECT id, definition_id, status, tier_level, credential_id, 
  FROM tb_learning_badges
 WHERE user_id = #{userId}
   AND definition_id = #{definitionId}
   FOR UPDATE

mapper.update:
UPDATE tb_learning_badges
   SET status = 'REVOKED', revoked_at = #{at}, updated_at = #{at}
 WHERE id = #{id} AND status = 'ISSUED'

UPDATE tb_learning_badges
   SET tier_level = #{tierLevel}, updated_at = #{at}
 WHERE id = #{id} AND status = 'ISSUED'

